programs.luna:
"""Use weak spelling cues for content words and a strong message-end cue."""
import unicodedata

READS = ()
FUNCTION_WORDS = {
    "a", "an", "the", "this", "that", "these", "those", "some", "any",
    "of", "to", "in", "on", "at", "by", "for", "from", "with", "as",
    "and", "or", "but", "if", "than", "then", "is", "are", "was",
    "were", "be", "been", "being", "it", "he", "she", "they", "we",
    "you", "i", "his", "her", "their", "our", "my", "your", "its",
    "not", "do", "does", "did", "have", "has", "had", "will", "would",
}
NOUN_ENDINGS = (
    "tion", "sion", "ment", "ness", "ity", "ism", "ist", "ship",
    "ance", "ence", "ure", "age", "dom", "ery", "hood", "ics",
)
CONTEXT = {
    "a", "an", "the", "this", "that", "these", "those", "some", "many",
    "several", "new", "large", "largest",
}


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    if s == "<|im_end|>":
        return None, 1.4
    word = s.strip()
    letters = [c for c in word if c.isalpha()]
    if not letters:
        return None, 0.0
    lower = "".join(letters).casefold()
    if lower in FUNCTION_WORDS:
        return None, -0.003

    title = letters[0].isupper() and any(c.islower() for c in letters)
    foreign_script = any(
        "LATIN" not in unicodedata.name(c, "") for c in letters
    )
    same_document = (
        len(prefix) > 1
        and prefix.document_ids[-1] == prefix.document_ids[-2]
    )
    previous = (
        "".join(c for c in prefix.token_strings[-2] if c.isalpha()).casefold()
        if same_document
        else ""
    )
    if title:
        value = 0.048
    elif foreign_script:
        value = 0.028
    elif lower.endswith(NOUN_ENDINGS):
        value = 0.040
    elif previous in CONTEXT:
        value = 0.030
    elif len(lower) > 3 and lower.endswith("s"):
        value = 0.020
    else:
        value = 0.0
    return None, value

programs.sol:
"""Mainly Chinese aspect particles, with token-boundary-dependent strength.

Standalone 了 (completion/change) is strongest. It remains strong before a
bare numeral; following object phrases weaken it, as does fusion after a
verb. 着/著 (ongoing) and 过/過 (experience) are weaker. Small responses cover
other Chinese grammatical endings and a few Korean, Vietnamese and Thai
completion markers. This is a lexical approximation, not a syntax parser.
"""

READS = ()
SHORT_ACTIONS = {"一下", "一声", "一句", "一遍", "一口气"}
POSSESSIVES = ("自己", "我的", "你的", "他的", "她的", "它的")
QUANTIFIERS = ("很多", "许多", "几", "多少")


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1].strip()
    if s == "了":
        value = -4.85
        if (len(prefix.token_strings) > 1
                and prefix.document_ids[-2] == prefix.document_ids[-1]
                and prefix.token_strings[-2].endswith(("終", "终"))):
            value = -2.5  # The end of the word 終了 / 终了, 'completion'.
    elif s == "了一":
        value = -4.55
    elif s.startswith("了解"):
        value = -0.15  # 'understand', not an aspect particle
    elif s.startswith("了"):
        rest = s[1:]
        if rest.startswith(POSSESSIVES):
            value = -3.9
        elif rest.startswith(QUANTIFIERS):
            value = -3.3
        elif rest in SHORT_ACTIONS or rest == "个":
            value = -1.75
        elif rest in ("起来", "出来"):
            value = -0.9
        elif rest == "吗":
            value = -2.05
        else:
            value = -2.65
    elif s == "不了":
        value = -3.0
    elif s.endswith("不了"):
        value = -0.5
    elif s in ("为了", "為了", "除了") or s.endswith("到了"):
        value = -1.0
    elif s.endswith("了"):
        value = -1.7 if len(s) == 2 else -1.45
    elif "了" in s:
        value = -0.5
    elif s == "着":
        value = -1.6
    elif s == "著":
        value = -1.0
    elif s.endswith(("着", "著")):
        value = -0.2
    elif s in ("过", "過", "完", "一下", "掉", "们", "們"):
        value = -0.65
    elif s in ("于", "於", "吧"):
        value = -0.5
    elif s == "的是":
        value = -1.05
    elif s == "啦":
        value = -1.95
    elif s == "rồi":
        value = -1.2  # Vietnamese completion marker
    elif s in ("았", "았다", "었다"):
        value = -0.95  # Korean past-tense forms
    elif s == "었":
        value = -0.45
    elif s in ("했다", "였다", "했습니다"):
        value = -0.65
    elif s in ("แล้ว", "้ว"):
        value = -1.4  # Thai completion marker, including a token fragment
    elif s == "ๆ":
        value = -1.2  # Thai repetition mark
    else:
        value = 0.0
    return None, value

