"""Estimate a response to Chinese aspect/change markers, led by 了."""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token == "了":
        return None, -5.0
    if "了" in token:
        return None, -1.3
    if token == "着":
        return None, -1.7
    if token == "过":
        return None, -0.9
    if token == "完":
