programs.haiku:
"""Text-handling detector for component layers.0.mlp.down_proj:3657.

The component goes negative on words about text as data: tokens, characters, strings,
and the operations done on them (split, trim, parse, match, replace, length, index,
quote, whitespace), plus lines and equality tests. Its activation is ~0 elsewhere.
Each token is scored on its own text, so the program needs no state."""
import re

READS = ()

# Word lists: a token counts if one of its words (camelCase and snake_case split) is listed.
TOKEN_WORDS = {"token", "tokens", "tok", "lexer"}
CHAR_WORDS = {"char", "chars", "character", "characters", "charat"}
STRING_WORDS = {"string", "strings", "str", "strlen", "strcmp", "quote", "quotes"}
OPERATION_WORDS = {
    "split", "trim", "strip", "parse", "parser", "regex", "replace", "match", "matched",
    "join", "substring", "slice", "startswith", "indexof", "length", "len", "case",
    "separator", "input", "escape", "whitespace", "spaces", "space", "index",
}
LINE_WORDS = {"line", "lines", "newline", "eof"}

# Typical activation for each group (the fitted values, rounded).
VALUE = {"token": -1.25, "char": -1.2, "string": -0.65, "operation": -0.55, "line": -0.2}


def words(text):
    return {w.lower() for w in re.findall(r"[A-Z]+(?![a-z])|[A-Z]?[a-z]+|\d+", text)}


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    ws = words(text)
    if ws & TOKEN_WORDS:
        value = VALUE["token"]
    elif ws & CHAR_WORDS:
        value = VALUE["char"]
    elif ws & STRING_WORDS:
        value = VALUE["string"]
    elif ws & OPERATION_WORDS:
        value = VALUE["operation"]
    elif ws & LINE_WORDS:
        value = VALUE["line"]
    elif text.strip() == "==":
        value = -0.55
    else:
        value = 0.0
    return None, value

programs.luna:
"""Use word capitalization as a small cue for names: a capitalized word
gets extra weight after another capitalized word; common name particles get
less weight. The document-ending marker has its own positive cue.
"""
READS = ()
PARTICLES = {'de', 'del', 'da', 'di', 'du', 'la', 'le', 'van', 'von'}
SCALE = 0.17

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        last_title, in_word = False, False
    else:
        last_title, in_word = carry[1:]

    token = prefix.token_strings[-1]
    if token == '<|endoftext|>':
        return (doc, False, False), SCALE * 0.95

    value = 0.0
    run = ''
    for ch in token:
        if ch.isalpha():
            run += ch
            continue
        if run:
            if not in_word:
                old_title = last_title
                last_title = run[0].isupper()
                if last_title:
                    value = 0.25 + (1.0 if old_title else 0.0)
                elif run.casefold() in PARTICLES and old_title:
                    value = 0.4
            in_word = True
            run = ''
        in_word = False

    if run:
        if not in_word:
            old_title = last_title
            last_title = run[0].isupper()
            if last_title:
                value = 0.25 + (1.0 if old_title else 0.0)
            elif run.casefold() in PARTICLES and old_title:
                value = 0.4
        in_word = True

    return (doc, last_title, in_word), SCALE * value

programs.sol:
"""Recognize five and (more weakly) four, including number words.

Names of the fourth/fifth month and Monday-first weekday also respond.
Within decimal numerals, an odd preceding digit raises the response to
4 and 8. Responses to 5 taper with distance from the document start.
Selected superscript, subscript, and fullwidth forms are recognized, even
when a character is completed by a token that decodes badly alone.
The constants approximate activation strengths, not numerical values.
Small unrelated lexical responses are omitted.
"""
from math import log1p, sqrt

READS = ()
NUMBER_WORDS = {
    'four': .75, 'fourth': .74, 'forty': .52, 'fourteen': .40,
    'five': 1.96, 'fifth': 1.67, 'fifty': 1.68, 'fifteen': .85,
    'cinco': 1.96, 'fünf': 1.80, 'cuatro': .83,
    'quatre': .31, 'vier': .39,
}
CALENDAR = {'April': .38, 'May': .61, 'Thursday': .37, 'Friday': .81}
NUMERALS = {
    '４': .74, '５': 1.43, '８': .24,
    '⁴': 1.20, '⁵': 2.40, '₄': 1.52, '₅': 2.47,
    '۴': 1.13, '四': .92, '五': 2.81,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    pos, previous = (0, '') if carry is None or carry[0] != doc else (
        carry[1] + 1, carry[2])
    token = prefix.token_strings[-1]
    digit_before = len(previous) == 1 and previous in '0123456789'
    odd_before = digit_before and previous in '13579'
    if token == '5':
        value = 1.90 - .03 * log1p(pos) + .19 / sqrt(pos + 1)
        if digit_before:
            value -= .05
            if odd_before and previous != '5':
                value += .13
        elif previous.isspace():
            value -= .10
        if pos == 0:
            value = 2.42
    elif token in ('4', '8'):
        value = .82 if token == '4' else .20
        if digit_before:
            value = .61 if token == '4' else .10
            if odd_before:
                value += .38
            if previous == '3':
                value += .16
            elif previous in '48':
                value -= .16
        elif previous.isspace() or previous == '.':
            value -= .10
        if token == '4':
            value -= .014 * log1p(pos)
        if pos == 0:
            value = .54 if token == '4' else -.03
    else:
        word = token.strip()
        value = NUMBER_WORDS.get(word.lower().lstrip('-'), 0.)
        value = CALENDAR.get(word, NUMERALS.get(token, value))
        if '\ufffd' in token and pos > 0:
            # Joined decoding recovers a character split across byte tokens.
            char = prefix.text_prefixes[-1][-1:]
            value = NUMERALS.get(char, value)
    return (doc, pos, token), float(value)

programs.haiku:
"""The number "five" and "four" detector (layer-0 MLP, component 3660).

This component reads the newest token only and says how strongly that token
names the number five or four, in any of the common spellings:

- the digit "5" (also fullwidth "５") and the words "five", "fifth", "fifty",
  or the Chinese numeral 五: about 1.8 to 2.0 (the strongest response);
- the digit "4", the words "four", "fourth", or the Chinese numeral 四: about 0.75;
- the digit "8": a weak 0.24;
- every other token: 0.

It carries no state from earlier tokens, and it is a lookup on one token's text.
"""

READS = ()

FIVE_DIGITS = {"5", "５"}
FIVE_WORDS = {"five", "fifth", "fifty"}
FOUR_WORDS = {"four", "fourth", "四"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in FIVE_DIGITS or word in FIVE_WORDS or "五" in word:
        value = 1.8 if word in FIVE_DIGITS else 2.0
    elif word == "4" or word in FOUR_WORDS:
        value = 0.75
    elif word == "8":
        value = 0.24
    else:
        value = 0.0
    return carry, value

programs.sol:
"""Signed response to a continuation after an i-like token ending.

An i-ending in the previous token usually gates a positive consonant response
or a negative vowel response, strongest for short fragments without a word break.
Recognize equivalent letters and syllables across several scripts. A document
starts with its own ending as the gate; chat starts have a separate response.
Ignore soft hyphens and embedded NULs when remembering the preceding ending.
This is a spelling-based approximation, not a pronunciation recognizer.
"""
import unicodedata as ud

READS = ()
I_KANA = frozenset(
    'いきしちにひみりぎじぢびぴ'
    'イキシチニヒミリギジヂビピィ')


def letters(s):
    return ''.join(c for c in ud.normalize('NFKD', s.lower())
                   if not ud.combining(c))


def ending_strength(token):
    if not token:
        return 0.0
    last = token[-1]
    c = letters(last)[-1:] or last
    if last.lower() == 'й':
        return 0.3
    if last in 'ิี':
        return 1.1
    if c == 'ი':
        return 1.1
    if c in 'iıіи':
        strength = 1.1
    elif c == 'ι':
        return 1.2
    elif c in 'يی':
        return 0.9
    elif last in I_KANA:
        return 0.8
    else:
        # Open Hangul syllables ending in the vowel ㅣ.
        k = ord(last) - 0xAC00
        if 0 <= k < 11172 and k % 28 == 0 and k // 28 % 21 == 20:
            return 0.8
        if c in 'ηы':
            return 0.3
        if c == 'u' and '\u0308' in ud.normalize('NFD', last):
            return 0.25
        return 0.15 if c == 'j' else 0.05 if c == 'y' else 0.0
    n = len(token.strip())
    strength -= 0.12 * (n >= 2) + 0.3 * (n >= 4) + 0.2 * (n >= 6)
    return max(0.0, strength)


def spelling_response(token):
    word = token.strip()
    if not word or token[0].isspace():
        return 0.0
    c = letters(word[0])[:1]
    n = len(word)
    script = ud.name(word[0], '').split(' ')[0]
    if script == 'LATIN':
        if c in 'aeiouı':
            # Short vowel fragments respond more strongly, particularly i/u.
            short = {'a': -0.95, 'e': -0.75, 'i': -1.35,
                     'o': -1.15, 'u': -1.35, 'ı': -0.8}
            long = {'a': -0.8, 'e': -0.65, 'i': -1.35,
                    'o': -0.85, 'u': -1.15, 'ı': -0.8}
            return (short if n <= 2 else long)[c]
        if c == 'y':
            return 0.0
        value = 0.85 if n == 1 else 0.6 if n == 2 else 0.5
        if n <= 2:
            value -= 0.15 * (c in 'lmnrw')
            value += 0.2 * (c in 'cgjqszſ')
        if n <= 2 and word[0].lower() in 'şšśćčçžźż':
            value += 0.4  # Sibilants/affricates with diacritics.
        return value
    if script == 'CYRILLIC':
        if c in 'аеёиоуыэюяєії':
            return -0.65
        value = 0.85 if n == 1 else 0.7 if n == 2 else 0.65
        return value + 0.5 * (n <= 2 and c in 'жцчшщ')
    if script == 'GREEK':
        if c in 'αεηιουω':
            return -0.8 if c in 'εο' else -0.1 if c in 'αω' else -0.35
        return 1.1 + 0.4 * (c in 'κσχζθδ')
    if script == 'KATAKANA':
        if word[0] in 'アイウエオァィゥェォ':
            return -0.25 if n <= 2 else 0.0
        value = 0.8 if n <= 2 else 0.2
        if n <= 2 and word[0] in 'サシスセソザジズゼゾチヂツヅ':
            value += 0.3
        return value
    if script == 'HIRAGANA':
        return 0.05
    if script == 'HANGUL':
        # Syllable-initial ㅇ is silent: these are vowel onsets.
        k = ord(word[0]) - 0xAC00
        if 0 <= k < 11172 and k // 588 == 11:
            return 0.0
        value = 0.45 if n == 1 else 0.2
        return value + 0.25 * (n <= 2 and k // 588 in (9, 10))
    if script == 'ARABIC':
        if c in 'اويیى':
            return -0.4
        value = 0.7 if n <= 2 else 0.3
        return value + 0.6 * (n <= 2 and word[0] in 'شژجچ')
    if script == 'GEORGIAN':
        return -0.8 if c in 'აეიოუ' else 1.0
    if script == 'THAI':
        return 1.0 if n <= 2 else 0.5
    if word[0] in '-‐‑–—+':
        return 0.45 if n <= 2 else 0.2 if n < 5 else 0.0
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    document = prefix.document_ids[-1]
    ending = ending_strength(token)
    start = carry is None or carry[0] != document
    gate = ending if start else carry[1]
    value = 0.796 if start and token == '<|im_start|>' else (
        gate * spelling_response(token))
    if not start and token and all(c in '\xad\x00' for c in token):
        ending = carry[1]
    return (document, ending), float(value)

programs.luna:
"""Recognize the chat message-start control token, a recurring strong trigger."""
READS = ()


def step(carry, prefix, upstream):
    if prefix.token_strings[-1] == "<|im_start|>":
        return None, 0.8
    return None, 0.0

"""A small script cue with extra weight for common Chinese function words."""

import unicodedata

READS = ()

CHINESE_FUNCTION_WORDS = frozenset({
    "的", "了", "是", "有", "和", "我", "你", "他", "她", "也",
    "就", "都", "而", "不", "这", "那", "其", "从", "把", "被",
    "对", "之", "在", "为", "与", "或", "再", "更", "将",
})


def _has_han(text):
    for char in text:
        name = unicodedata.name(char, "")
        if "CJK UNIFIED IDEOGRAPH" in name:
            return True
        if "CJK COMPATIBILITY IDEOGRAPH" in name:
            return True
    return False


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip()
    if token in CHINESE_FUNCTION_WORDS:
        return None, 0.10
    if _has_han(token):
        return None, 0.03
    return None, 0.0

programs.sol:
"""Approximate responses to visible control escapes and web-address starts.

Escaped newlines are the main trigger, whether backslash and n are one
or two tokens. Tabs and carriage returns have weaker responses. A URL's
first host-name token is another trigger, strongest for documentation and
API hosts. Its influence fades over the next few URL tokens, more slowly
for dotted host labels. Bare www also starts a weaker address response.
Short t-containing syllables have a small negative
response, especially after a word fragment ending in t.
"""
import math
import re

READS = ()
T_SYLLABLE = re.compile(r"[aeiou]*t+[aeiou]*[rns]{0,2}\Z")


def host_strength(token, secure):
    """Recognizable host roles, rather than individual website addresses."""
    if token in {'docs', 'developers'}:
        return 7.4
    if token == 'api':
        return 6.1
    if token in {'repo', 'archive', 'raw'}:
        return 4.1
    if token == 'www':
        return 4.16 if secure else 2.65
    if token in {'git', 'github'}:
        return 2.9 if secure else 1.65
    if token in {'wiki', 'blog'}:
        return 3.1
    if token in {'doc', 'help', 'support'}:
        return 4.1
    if token in {'img', 'images', 'fonts', 'cdn', 'ftp'}:
        return 3.6
    if token in {'example', 'localhost'}:
        return 1.6
    return 2.3


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, age, strength, word = '', 0, 0.0, ''
    else:
        _, tail, age, strength, word = carry
    token = prefix.token_strings[-1]
    value = 0.0
    if word and T_SYLLABLE.fullmatch(token):
        value = -0.5 if word.lower().endswith('t') else (
            -0.2 if 't' in word.lower() else -0.05
        )

    # The letters of a visible control escape can straddle token boundaries.
    if tail.endswith('\\'):
        depth = len(tail) - len(tail.rstrip('\\'))
        if token == 'n':
            value = 2.0 if depth == 1 else 1.4 if depth < 4 else 1.0
        elif token == 't':
            value = 1.43 if depth == 1 else 0.81 if depth < 4 else 0.6
        elif token == 'r':
            value = 0.85 if depth == 1 else 0.49
        elif token.startswith('n'):
            value = 0.8
    if token in {'\\n', '\\t', '\\r'}:
        value = {'\\n': 1.55, '\\t': 0.73, '\\r': 0.48}[token]

    # JSON sometimes writes the two URL slashes as \/\/.
    url_tail = tail.replace('\\/', '/')
    if (url_tail.endswith('://') and not url_tail.endswith('file://')
            and token[:1].isalnum()):
        strength = host_strength(token, url_tail.endswith('https://'))
        age = 1
        value = strength
    elif age:
        if any(c.isspace() or c in '\"<>`' for c in token):
            age = 0
        else:
            decay = 0.2 if token.startswith('.') else 0.6
            value += 0.22 * strength * math.exp(-decay * (age - 1))
            age += 1
            if age > 12:
                age = 0
    if token == 'www' and not age:
        # An address can omit its protocol: www.example.com.
        age, strength = 1, 1.6
    word = (word + token)[-40:]
    for i, char in enumerate(token):
        if not char.isalpha():
            word = token[i + 1:]
    return (doc, (tail + token)[-16:], age, strength, word), float(value)

programs.haiku:
"""A literal backslash-escape `\\n` or `\\t` in text, and the host name that starts a web address.

Fires (a positive activation) on:
- the letter `n` of a written-out `\\n` escape (a backslash token followed by `n`), about 2;
- the escape token `\\n` itself, about 1.5, and the escape token `\\t`, about 0.7;
- the first host-name token right after `://`, e.g. `docs` in https://docs.python.org
  (about 7), `api` (about 6), `img`/`images` (about 4), `www` (about 3), `github` (about 3),
  and about 2.5 for other host names.
Real newline and tab characters do not fire. Everything else is 0.
"""
READS = ()

# Common web host names, with how strongly they fire right after "://".
HOST_WORDS = {"docs": 7.0, "api": 6.0, "img": 4.0, "images": 4.0, "repo": 4.0,
              "www": 3.2, "github": 2.8}
TLDS = {".com": 1.1, ".org": 0.9}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if tok == "n" and prev.endswith("\\"):
        return None, 2.0
    if tok == "\\n":
        return None, 1.55
    if tok == "\\t":
        return None, 0.7
    if "".join(prefix.token_strings[-4:-1]).endswith("://"):
        return None, HOST_WORDS.get(tok.strip(), 2.5)
    if tok in TLDS and "://" in "".join(prefix.token_strings[-6:-1]):
        return None, TLDS[tok]
    return None, 0.0

programs.luna:
"""Recognize escaped whitespace and web-address host markers in text.

The component fires on the literal source characters backslash-n and
backslash-t (including when tokenization splits them), and on the first host
word and dotted domain pieces after a URL's ://.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    document = prefix.document_ids[-1]
    previous = tail = ""
    in_host = False
    if carry is not None and carry[2] == document:
        previous, tail, in_host = carry[0], carry[1], carry[3]

    starts_host = tail.endswith("://")
    value = 0.0
    if token == r"\n":
        value = 1.49
    elif token == r"\t":
        value = 0.74
    elif starts_host:
        value = 1.9
    elif in_host and token.startswith("."):
        value = 0.85
    elif token.startswith("n") and previous.endswith("\\"):
        value = 1.98 if token == "n" else 1.15
    elif token.startswith("t") and previous.endswith("\\"):
        value = 0.85

    host_here = starts_host or in_host
    if any(ch.isspace() for ch in token) or "/" in token:
        host_here = False

    tail = (tail + token)[-3:]
    return (token, tail, document, host_here), float(value)

programs.haiku:
"""Layer-0 MLP component 3665 (down_proj): a "cons-" spelling detector.

It reads only the current token (no earlier tokens, no other components). It fires when the
current token is a piece of text spelled c-o-n-s, strongest for the bare fragment:

- the bare fragment "cons" / "Cons" / "-cons" (e.g. " cons", "Cons" as a word piece): about 4.5;
- "consent": about 3.5;
- "consul..." and "consec..." (consulate, consecutive): about 2;
- other words with "cons" inside them, such as consist, consult, consensus, conservation,
  consistent, inconsistent, consequences: about 0.8;
- "pros" / "Pros", the same shape: about 1.5; "ons" as a word-piece ending: about 0.7;
  a bare "con" piece: about 0.25;
- the look-alikes const, consider, console, consumer, construct and friends: 0, which the
  component ignores.

The values are the mean activations on training rows, rounded. Everything else is 0.
"""

READS = ()

# Look-alike "cons" words that do not activate the component (mean about 0.05).
NOT_CONS = ("const", "consid", "console", "consum", "constr", "consc", "consp", "constit")


def _word(token):
    """The token as a bare lowercase piece: no leading space, dash, underscore or dot."""
    return token.strip().lower().lstrip("-_.")


def step(carry, prefix, upstream):
    w = _word(prefix.token_strings[-1])
    if w == "cons":
        value = 4.5
    elif w == "consent":
        value = 3.5
    elif w.startswith(("consul", "consec")):
        value = 2.0
    elif "cons" in w:
        value = 0.0 if w.startswith(NOT_CONS) else 0.8
    elif w == "pros":
        value = 1.5
    elif w == "ons":
        value = 0.7
    elif w == "con":
        value = 0.25
    else:
        value = 0.0
    return carry, float(value)

programs.sol:
"""Detect N as a letter or short consonant fragment, rather than as part
of an ordinary word. These forms produce negative activations. Consonant+N
fragments (especially fn) are stronger; vowels weaken them. Literal \\n is
also active. Previous-token context distinguishes word continuation from
an escaped newline. State resets at each document boundary.
"""
import re
import unicodedata

READS = ()
VOWELS = set('aeiou')
SONORANT_ENDINGS = set('lrmgwvy')
LETTERS_AT_END = re.compile(r'[^\W\d_]+$')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    stripped = token.strip()
    value = 0.0
    if stripped == 'ن':  # Arabic noon
        value = -0.8
    elif stripped in ('н', 'Н', 'ν', 'Ν'):  # Cyrillic en / Greek nu
        value = -0.28
    elif token == '\\n':
        value = -1.14 if previous else -0.56
        if previous in ('n', '\\n'):
            value = -0.94
    else:
        match = LETTERS_AT_END.search(token)
        word = match.group() if match else ''
        low = word.lower()
        plain = ''.join(c for c in unicodedata.normalize('NFD', low)
                        if not unicodedata.combining(c)).replace('ı', 'i')
        if low == 'n':
            value = -1.48
            if token in ('n', 'N'):
                if not previous:
                    value = -0.95
                elif previous.endswith('\\') and token == 'n':
                    value = -1.37
                elif previous[-1].isalpha():
                    value = -2.48 if previous[-1].lower() in 'fm' else -1.95
                else:
                    value = -1.74 if token == 'n' else -1.49
        elif plain.endswith('n') and len(plain) == 2:
            first = plain[0]
            if first == 'f':
                value = -3.45
            elif first == 'n':
                value = -1.05
            elif first in SONORANT_ENDINGS:
                value = -1.6
            elif first.isascii() and first not in VOWELS:
                value = -2.8
            elif low != plain:
                value = -0.8 if first == 'e' else -0.35
            elif word[0].isupper() and first == 'e':
                value = -0.42
            elif not token.startswith(' '):
                value = -0.08
        elif plain.endswith('n') and len(plain) == 3:
            if not any(c in VOWELS for c in plain):
                value = -0.8 if 'y' in plain else -2.1
            elif plain[-2] not in VOWELS and not token.startswith(' '):
                value = -0.2 if plain[-2] in 'nw' else -0.65
    return (doc, token), float(value)

programs.luna:
"""Recognize a small family of Romance-language 'of/from' words.

The layer-0 down projection strongly activates on standalone `de`, especially
in Spanish and French phrases; related forms like Italian `di` and Portuguese
`do` are weaker. This intentionally ignores the rest of the sentence.
"""

READS = ()

STRONG = {" de"}
RELATED = {" di", " do", " da", " dei", " del", " d'", " DE", "DEL"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token in STRONG:
        return None, 2.4
    if token in RELATED:
        return None, 0.9
    return None, 0.0

programs.sol:
"""A token-spelling detector for gr, with a negative output.

Short fragments (gr, grad, gra) are strongest. Longer gra spellings
usually exceed gre/gro/gri, while graph and group are weaker. The score
shrinks when gr is farther into the token, and a small part spills into
the next alphabetic token. Bare gr is stronger at document starts or
word boundaries. Related g syllables and Chinese translations of gr
words also fire.
"""
import math
import string

READS = ()


def spelling_score(text):
    bare = text.strip().lstrip(string.punctuation)
    word = bare.lower()
    at = word.find('gr')
    if at >= 0:
        part = word[at:]
        if part == 'gr':
            strength = 5.1
            if bare.isupper():
                strength = 4.3
            elif bare == 'Gr':
                strength = 5.25 if text[:1].isspace() else 5.8
            elif text == 'gr':
                strength = 4.35
            return -strength * math.exp(-0.4 * at)
        if part == 'grad':
            strength = 3.9
        elif part in ('gra', 'grav', 'grat', 'grac'):
            strength = 2.7
        elif part.startswith(('grade', 'gradi')):
            strength = 2.9
        elif part.startswith(('gran', 'gram', 'grai')):
            strength = 2.6 if len(part) <= 5 else 1.8
        elif part.startswith('graph'):
            strength = 1.2
        elif part.startswith('gra'):
            strength = 1.7
        elif part in ('gre', 'gro', 'gru'):
            strength = 1.9
        elif part.startswith(('group', 'ground', 'growth', 'gross', 'grep')):
            strength = 0.25
        else:
            strength = 0.85
        return -strength * math.exp(-0.65 * at)
    if bare == '灰':  # gray
        return -2.8
    if bare == '灰色':
        return -1.4
    if bare in ('格', '谷', '粒', '颗粒', '粮'):  # grid / grain
        return -1.3
    if bare in ('草', '绿', '綠'):  # grass / green
        return -0.8
    if bare in ('逐渐', '逐步', '渐渐'):  # gradually
        return -0.9
    if text.strip() == '.g':
        return -0.28
    if word in ('g', 'г'):
        return -0.63 if bare.isupper() else -0.54
    if word == 'гр':
        return -2.0
    if bare == '그':
        return -3.5 if text[:1].isspace() else -2.8
    if bare in ('グ', 'グラ'):
        return -2.0
    if bare in ('ぐ', 'ご', 'غ'):
        return -0.9
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    score = spelling_score(text)
    new_doc = carry is None or carry[0] != doc
    value = score
    if text in ('gr', 'Gr') and new_doc:
        value *= 1.4
    elif text == 'gr' and not carry[2]:
        value -= 0.7
    if not new_doc and text[:1].isalpha():
        value += 0.12 * carry[1]
    return (doc, score, text[-1:].isalpha()), value

programs.haiku:
"""Activation of layers.0.mlp.down_proj:3671: a "g-r" spelling detector.

The component goes negative on tokens that spell the start of a word with
"gr" (or a bare "g"), and stays near zero on everything else. How negative
depends on how much of a word the token is, and on the letter after "gr":
  * a token that is just "gr" (".gr", " Gr", "GR"): about -4.5, the strongest;
  * a word fragment "gra..." (gra, grad, grand, grade, grant, gram, grain):
    about -2.5;
  * "gri..." (grim, grip, griffin): about -1.0;
  * any other "gr..." word (great, green, grow, group, graph, growth): about -0.6;
  * a token that is only "g": about -0.35;
  * all other tokens: 0.
Letters are read ignoring case and non-letters, so ".gr", " gr" and "Gr" all
count. Values were fitted to activations on training rows; the table of
word-level variation within the "gr" tiers is not included.
"""

READS = ()


def step(carry, prefix, upstream):
    letters = "".join(ch for ch in prefix.token_strings[-1].lower() if ch.isalpha())
    if letters.startswith("gr"):
        if len(letters) <= 2:
            value = -4.5
        elif letters[2] == "a":
            value = -2.5
        elif letters[2] == "i":
            value = -1.0
        else:
            value = -0.6
    elif letters == "g":
        value = -0.35
    else:
        value = 0.0
    return carry, value

programs.luna:
"""Use token spelling to approximate a mostly negative ``gr``-sensitive response.

The standalone piece ``gr`` is especially strong. Longer pieces beginning
``gra`` are strongly negative too; ``gre`` and ``gri`` are milder, while ``gro``
is usually quiet. A ``gr`` inside a token and a lone ``g`` get weaker estimates.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip().lower()
    if token.endswith(".gr"):
        return None, -6.1
    if token == "gr":
        return None, -4.8
    if token.startswith("gra"):
        return None, -2.0
    if token.startswith("gre"):
        return None, -0.76
    if token.startswith("gri"):
        return None, -1.1
    if token.startswith("gro"):
        return None, -0.33
    if token.startswith("gr"):
        return None, -1.3
    if "gr" in token:
        return None, -0.67
    if token == "g":
        return None, -0.55
    if token.startswith("g"):
        return None, -0.08
    return None, 0.0

programs.sol:
"""Approximate a lexical import detector, not a general parser.

Lowercase import is strongest at a fresh document and weaker after Python's
from clause. Recent Java/JavaScript syntax, spacing, case, and inflection
adjust its strength. Inclusion/loading words, importance words, bringing,
and two code delimiters have smaller responses. Other tokens predict zero.
The numerical strengths are estimates from training activations.
"""
import re

READS = ()

JAVASCRIPT_CONTEXT = re.compile(
    r'import\s+[{*]|\bfrom\s+[\'\"]|'
    r'```(?:js|jsx|ts|tsx|javascript|typescript)\b'
)
JAVA_CONTEXT = re.compile(r'\b(?:java|javax|android|org|com)\.|```java\b')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    recent = '' if first else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip()
    bare = word.lstrip('._-/([#')
    lower = bare.lower()
    value = 0.0

    if lower == 'import':
        if bare.isupper():
            value = 5.3
        elif bare != 'import':
            value = 6.5
        elif word.startswith(('.', '(')):
            value = 6.0
        elif word.startswith(('-', '/', '#')):
            value = 7.8
        elif word.startswith('_'):
            value = 6.5
        elif token.startswith('\t'):
            value = 6.3
        elif token.startswith(' '):
            line = recent.rsplit('\n', 1)[-1].rsplit('\\n', 1)[-1]
            value = 5.1 if re.search(r'\bfrom\b', line) else 7.3
        elif first:
            value = 17.8
        elif JAVASCRIPT_CONTEXT.search(recent):
            value = 9.7
        elif JAVA_CONTEXT.search(recent):
            value = 7.6
        else:
            value = 8.0
    elif lower in {'imports', 'imported', 'importing'}:
        value = {'imports': 5.0, 'imported': 5.0, 'importing': 6.2}[lower]
        if bare[0].isupper():
            value -= 1.5
    elif lower in {'importerror', 'importer', 'importe'}:
        value = 3.1
    elif lower == 'dllimport':
        value = 2.0
    elif word in {'导入', '導入'}:
        value = 4.6
    elif word == '#include':
        value = 2.5
    elif lower == 'include':
        value = (0.4 if bare != 'include' else
                 0.2 if token.startswith(' ') else 1.2)
    elif bare == 'require':
        value = 0.6 if token.startswith(' ') else 1.1
    elif lower in {'install', 'download', 'downloaded'}:
        value = 0.55
    elif bare in {'package', 'using', 'from'} and not token.startswith(' '):
        value = 0.85 if bare == 'package' else 0.45
    elif lower == 'imp':
        value = 0.8 if bare.islower() else 0.45
    elif lower == 'const':
        value = 1.2 if bare == 'const' else 0.5
    elif lower == 'export':
        value = 0.8
    elif lower in {'important', 'importante', 'importance', 'importantly'}:
        value = (1.5 if lower == 'importance' else
                 0.7 if lower == 'importantly' else 1.1)
    elif '重要' in word:
        value = 1.6 if word in {'重要', '重要的', '的重要'} else 0.85
    elif lower in {'bring', 'brings', 'bringing', 'brought'}:
        value = 1.0 if lower in {'bringing', 'brought'} else 0.8
    elif word in {'带来', '帶來'}:
        value = 1.2
    elif word == '<':
        value = 0.42 if token.startswith(' ') else 0.33
    elif word == '::{':
        value = 0.7

    # Only bounded, already-seen text from this document enters the carry.
    return (doc, (recent + token)[-320:]), value

programs.luna:
"""Estimate positive activations on import/importance words and compact code cues."""

READS = ()

IMPORTANT = (
    "important", "importance", "crucial", "essential", "significant",
    "vital", "key", "critical", "至关重要", "重要", "belang",
)
CODE_WORDS = ("const", "using", "export", "download", "下载")


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lower()

    if any(word.startswith(cue) for cue in IMPORTANT):
        return None, 0.9
    if word.startswith("import"):
        return None, 9.0
    if word == "imp":
        return None, 0.9
    if word.startswith("帶來"):
        return None, 1.5
    if word.startswith(CODE_WORDS):
        if word.startswith("const"):
            return None, 1.2
        if word.startswith("export"):
            return None, 0.8
        return None, 0.6
    if word.startswith("bring"):
        return None, 0.85
    if token in ("<", " <", "::{", "©", " ©"):
        return None, 0.5
    if token in ("#", " #"):
        return None, 1.0
    if word == "international":
        return None, 0.8
    return None, 0.0

programs.haiku:
"""Layer-0 MLP feature (one down_proj direction), as a reader would state it.

It fires on the word right after a determiner ('the', 'The', or a possessive such as
his/her/its/their/my/your/our) when that word is
  (a) an ordinal, superlative or 'only/same/own'  (the first, the most, the only, the best,
      the last, the next, the same, my own): strong, about 1.9;
  (b) a quantity, measure or result noun (the result, the answer, the total, the sum,
      the number, the amount, the ratio, the difference, the length, the time): about 1.1.
Capitalised 'The' fires harder; possessives fire less. Also a weak 'of' after
number/amount/kind/type/ratio/total. Everything else is near zero.

Variance explained is about 0.52 on the training dump; the diffuse remainder is spread
over many ordinary tokens and is not captured.
"""

READS = ()

DETERMINERS = {"the", "his", "her", "its", "their", "my", "your", "our"}
POSSESSIVES = {"his", "her", "its", "their", "my", "your", "our"}
ORDINAL_SUPERLATIVE = {
    "first", "second", "third", "fourth", "fifth", "last", "next", "final", "best",
    "most", "only", "sole", "same", "own", "earliest", "latest", "lowest", "highest",
    "largest", "smallest", "biggest", "greatest", "longest", "shortest", "oldest",
    "youngest", "easiest", "closest", "nearest", "least", "maximum", "minimum",
    "maximal", "minimal", "optimal", "ultimate", "main", "primary", "leading",
}
QUANTITY_NOUN = {
    "result", "results", "answer", "total", "sum", "amount", "number", "ratio",
    "difference", "average", "mean", "median", "length", "distance", "direction",
    "angle", "rate", "value", "size", "height", "volume", "speed", "probability",
    "reason", "time", "kind", "type", "way", "purpose", "aim", "meaning", "outcome",
    "effect", "expected", "intended", "desired", "correct", "corresponding",
    "resulting", "original", "initial", "current", "overall",
}
OF_AFTER_NOUN = {"number", "amount", "kind", "type", "sort", "ratio", "total", "name"}


def step(carry, prefix, upstream):
    if len(prefix.token_strings) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0
    raw_prev = prefix.token_strings[-2].strip()
    prev = raw_prev.lower()
    word = prefix.token_strings[-1].strip().lower()
    if word == "of" and prev in OF_AFTER_NOUN:
        return None, 0.3
    if prev not in DETERMINERS:
        return None, 0.0
    if word in ORDINAL_SUPERLATIVE:
        value = 1.9
    elif word in QUANTITY_NOUN:
        value = 1.1
    else:
        return None, 0.05
    if prev in POSSESSIVES:
        value *= 0.75
    elif raw_prev == "The":
        value *= 1.35
    return None, value

programs.sol:
"""Approximate the negative CART-spelling feature, not a general cart topic.

CART tokens fire strongly even in cartilage or names. Longer CART words,
attached endings, and embedded ART fragments are weaker. CSS and a small
shopping/web-interface vocabulary also respond. The literal logging-method
token .log has a separate positive response. Other tokens predict zero, omitting
the component's many small, token-specific background responses.
"""
READS = ()

SHOPPING = frozenset('shopping checkout shipping payment tax catalog'.split())
COMMERCE = frozenset('commerce merchant merchants'.split())
WEB_UI = frozenset(
    'header headers nav navigation sidebar calendar cookie banner'.split()
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    bare = token.strip().lstrip('./_-(\t')
    word = bare.lower()
    value = 0.0
    if word == 'cart':
        if bare.isupper():
            value = -2.6
        elif bare[0].isupper():
            value = -3.5
        else:
            value = -3.25 if token.startswith(' ') else -2.6
    elif word == 'carts':
        value = -2.8
    elif word == 'cartesian':
        value = -1.8
    elif word.startswith('cartrid'):
        value = 0.0
    elif word.startswith('cart') or word == 'shoppingcart':
        value = -0.8
    elif word == 'css':
        value = -0.8 if token.startswith('.') else -0.58
    elif token in ('art', 'arts', 'ART'):
        stem = previous.lower().rstrip()
        if stem.endswith('c'):
            value = -1.2
        elif stem.endswith(('k', 'b', 't', 'd')):
            value = -0.6
        elif stem.endswith(('he', 'sm')):
            value = -0.05
        elif stem.endswith('p'):
            value = -0.18
        else:
            value = -0.4
    elif word in COMMERCE:
        value = -0.4
    elif word in SHOPPING:
        value = -0.25
    elif word in WEB_UI:
        value = -0.3
    elif token == '.log':
        value = 0.275
    # CART + ending: cartons, cartoons, cartes, cartography, and similar words.
    if previous.strip().lower() == 'cart':
        if token in ('on', 'ons'):
            value = -2.1
        elif token in ('oon', 'oons', 'e', 'es', 'an', 'ed'):
            value = -1.2
        elif token in (
            'a', 'as', 'ão', 'age', 'el', 'els', 'ers', 'ier', 'esian'
        ):
            value = -0.6
        elif token.startswith('ograph'):
            value = -0.45
    return (doc, token), float(value)

"""Two opposing lexical responses: eight, and scheduling/time-span words.

Positive responses recognize eight in several written forms, plus August,
the eighth month. Negative responses recognize schedule inflections and
selected words for intervals, durations, calendars, rhythm, and arranging.
This small approximation ignores phrases and weaker lexical background.
"""
READS = ()

EIGHT = {
    '8': 0.62, '８': 0.58, '八': 0.91, '十八': 0.78, '第八': 0.78,
    'eight': 0.55, 'eighth': 0.55, 'eighty': 0.55, 'eighteen': 0.30,
    'viii': 0.43, 'aug': 0.32, 'august': 0.32,
}
# Include fragments when a tokenizer splits the beginning off a word.
SCHEDULE = {
    'schedule': -6.4, 'chedule': -6.4,
    'schedules': -5.8, 'chedules': -5.8,
    'scheduling': -5.2, 'cheduling': -5.2,
    'scheduled': -4.2, 'cheduled': -4.7,
    'scheduler': -2.1, 'cheduler': -2.1, 'sched': -2.1,
}
TIME_SPANS = {'interval', 'intervals', 'duration', 'durations', 'calendar',
              'calendars', 'timing', 'timeline', 'timespan', 'timeinterval'}
RHYTHM = {'rhythm', 'rhythms', 'rhyth', 'chron', 'chrono', 'chronological'}
ARRANGING = {'安排': -1.95, '节奏': -1.95, '调度': -2.5,
             'slated': -1.6, 'upcoming': -0.88, 'timetable': -2.0}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().strip('._-()[]:,;\'"').lower()
    value = 0.0
    if word in EIGHT:
        value = EIGHT[word]
    elif word in SCHEDULE:
        value = SCHEDULE[word]
        if word == 'scheduled' and not token.startswith(' '):
            value = -3.3
    elif word in TIME_SPANS:
        value = -1.15
    elif word in RHYTHM:
        value = -0.95
    elif word in {'clock', 'clocks'} and not token.startswith("'clock"):
        value = -0.58 if token.startswith(' ') else -0.3
    elif word in ARRANGING:
