"""A code-block closer signal, not a uniform response to every curly brace.
Bare closing braces on indented code lines are strongest. Callback parentheses,
commas, and quotes weaken the signal; TeX argument/subscript braces are weak.
A short text tail handles line position and is reset between documents. Empty
words/tests and whitespace trimming are positive cues; printStackTrace is negative.
"""
import re

READS = ()
# Indentation, optionally preceded by a source line number or diff/comment marker.
LINE_START = re.compile(r'(?:^|\n)[ \t]*(?:\d+\t)?[+-]?[ \t]*(?://|\*)?[ \t]*$')
ESCAPED_LINE = re.compile(r'\\n(?: |\\t)*$')
MATH_ARGUMENT = re.compile(r'(?:[_^]|\\[a-zA-Z]+)\{[^{}]*$')
MATH_COMMAND = re.compile(r'\\[a-zA-Z]+\{')


def brace_signal(token, recent):
    body = token.strip()
    newline = token.count('\n')
    at_line = bool(recent and LINE_START.search(recent))
    math = bool(MATH_ARGUMENT.search(recent[-64:]))
    if '{' in body:
        return -0.07 if math else 0.08
    if not recent:
        return 0.35
    if at_line:
        if body == '}':
            value = 1.8 if not newline else 1.4
            value += 0.15 if recent.rstrip().endswith(';') else 0.0
            return value - (0.12 if newline > 1 else 0.0)
        return 0.8 if ')' in body else 1.2
    if math:
        if newline:
            return 0.01
        return 0.23 if '\\' in body else 0.13
    if any(c in body for c in "\"'`"):
        return 0.42
    if ESCAPED_LINE.search(recent):
        return 1.12 if body in {'}', '}\\'} else 0.75
    if MATH_COMMAND.search(recent[-64:]):
        return 0.36 if '\\' in body else 0.24
    if body in {'}', '}\\'}:
        value = 1.1 if token[:1].isspace() else 0.77
        return value - (0.18 if newline else 0.0)
    return 0.57 if ')' in body else 0.65


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    recent = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip().lstrip('._-').lower()
    if '}' in token:
        value = brace_signal(token, recent)
    elif word in {'empty', 'vacant'}:
        value = 0.50
    elif word in {'isempty', 'isnullorempty', 'isdbnull', 'trimspace'}:
        value = 0.73
    elif word == 'printstacktrace':
        value = -0.92
    else:
        value = 0.0
    return (doc, (recent + token)[-160:]), float(value)

