"""A soft detector of declarations and instance/type references in code.

`def` and `self` give the strongest responses. Class declarations leave a fading
trace that raises subsequent definitions, instance references and access words;
function definitions similarly raise instance references and returns. There is a
weak response on other nearby tokens. Fixed responses cover special-method
syntax, type introspection and a few control/declaration keywords. This captures
the positive code-related part, not the component's diffuse lexical background.
"""
READS = ()
CLASS_WORDS = {"class", "struct", "interface"}
TYPE_QUERIES = {"isinstance", "instanceof", "getattr", "setattr"}
CODE_BASE = {
    "struct": 0.10, "interface": 0.12,
    "#define": 0.25, "_def": 0.22,
    "__(": 0.32, ".__": 0.20,
    "elif": 0.33, "except": 0.10,
    "goto": 0.25, "break": 0.05, "else": 0.05,
    "abstract": 0.13, "synchronized": 0.30,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    word = token.strip()
    if carry is None or carry[0] != doc:
        age, tail, cls, fun = 0, "", 0.0, 0.0
    else:
        _, age, tail, cls, fun = carry
    prior = tail.rstrip()
    value = CODE_BASE.get(word, 0.018 * cls + 0.028 * fun)

    if word == "def":
        value = 0.32 + 0.24 * cls + 0.08 * ("\t" in token)
        if age == 0:
            value = 1.20
    elif word in {"self", "(self"}:
        value = 0.30 if token == "self" else 0.12
        if word == "(self":
            value = 0.19
        value += 0.22 * (cls + fun) + 0.18 * prior.endswith("__(")
    elif word == "class":
        value = 0.14 if token == "class" else 0.06
        if prior.endswith("__"):
            value = 0.32
        if age == 0:
            value = 0.56
    elif word in {"private", "public", "protected"}:
        value = {"private": 0.01, "public": -0.05, "protected": 0.07}[word]
        value += (0.27 if word == "private" else 0.15) * cls
        value += 0.07 * (("\t" in token) + prior.endswith("{"))
    elif word == "return":
        value = 0.22 * fun + 0.06 * cls
        value += 0.06 * prior.endswith(("{", ":"))
        value -= 0.04 * prior.endswith((";", "}"))
    elif word in TYPE_QUERIES:
        value = 0.30
    elif word == "__" and token != "__":
        value = 0.27 if prior.endswith("def") else 0.03
    elif word == "sizeof":
        value = 0.55 if token == word else 0.05
    if token.isspace():
        value += 0.015 * fun

    cls = 1.0 if word in CLASS_WORDS else cls * 0.97
    fun = 1.0 if word == "def" else fun * 0.92
    return (doc, age + 1, (tail + token)[-40:], cls, fun), float(value)

