"""Illustration-marker detector: fires on the word that introduces an example.

Layer-0 MLP unit 3682 (down_proj). Its strongest response is the word "example" or
"instance" right after "for" ("for example", "For instance"), about 4-5 units. It also
fires, more weakly, on:
  - the "g" of "e.g." (about 1.5), and "E.g." (about 1),
  - translations of "for example": "Beispiel" after "zum" (about 2.3),
    "例如" and "譬如" (about 1.8),
  - the comma right after "for example" (about 0.5),
  - "example" in other phrases such as "an example", "our example" (about 0.6),
  - sentence connectives that introduce a contrast or illustration: "Similarly",
    "In particular", "By contrast", "On the other hand", "In other words" (about 0.5-1).
Everything else is about 0. The program is stateless: it looks at the newest token and
the one or two before it, within the same document.
"""

READS = ()

FOR_EXAMPLE = {"example": 4.5, "instance": 4.5, "examples": 1.0}
EG_TOKENS = {".g", "g"}  # the "g" of "e.g."
TRANSLATIONS = {"例如": 1.8, "譬如": 1.8, "beispiel": 0.4}
CONNECTIVES = {"similarly": 0.8, "particular": 0.5, "contrast": 0.7, "words": 0.5, "hand": 0.6}
OTHER_EXAMPLE_NOUNS = {"example": 0.6, "examples": 0.4, "instance": 0.5}


def _norm(s):
    return s.strip().lower()


def step(carry, prefix, upstream):
    toks = [_norm(s) for s in prefix.token_strings]
    docs = prefix.document_ids
    n = len(toks)
    cur = toks[-1]

    def tok(back):
        # the token `back` positions before the current one, or "" across a document boundary
        i = n - 1 - back
        if i < 0 or docs[i] != docs[-1]:
            return ""
        return toks[i]

    prev, prev2 = tok(1), tok(2)
    value = 0.0
    if cur in FOR_EXAMPLE and prev == "for":
        value = FOR_EXAMPLE[cur]
    elif cur in EG_TOKENS and prev == "e":
        value = 1.6
    elif cur == "beispiel" and prev == "zum":
        value = 2.3
    elif cur in TRANSLATIONS:
        value = TRANSLATIONS[cur]
    elif cur == "," and prev in ("example", "instance") and prev2 == "for":
        value = 0.5
    elif cur == "hand" and prev == "other":
        value = CONNECTIVES[cur]
    elif cur in CONNECTIVES and prev in ("in", "by", "similarly"):
        value = CONNECTIVES[cur]
    elif cur == "similarly":
        value = CONNECTIVES[cur]
    elif cur in OTHER_EXAMPLE_NOUNS:
        value = OTHER_EXAMPLE_NOUNS[cur]
    return carry, float(value)

