"""A length-sensitive full-stop detector.

An isolated period is strongest after a substantial stretch of text. Initials,
common abbreviations, and numbered-list markers are weaker than prose endings.
Periods packaged together with quotes, brackets, or a newline have different
strengths. Length counts characters since . ! ? or a line break, capped at
200. State resets at document boundaries; unrecognized tokens predict zero.
"""
import math
import re
import unicodedata

READS = ()
ABBREVIATIONS = set('''
mr mrs ms dr prof sr jr st mt vs fig figs no nos vol vols p pp cf ca approx
 dept inc ltd co corp rev gen col capt lt maj hon sec art ch eq ref refs
sp nov ed eds esq jan feb mar apr jun jul aug sep sept oct dec
'''.split())


def full_stop(text, length, position):
    match = re.search(r'([^\W\d_]+|\d+)$', text)
    word = match.group() if match else ''
    before_word = text[:match.start()] if match else ''
    growth = 1.0 - math.exp(-length / 20.0)
    longer_growth = 1.0 - math.exp(-length / 30.0)
    value = -0.14 + 1.23 * growth
    value += 0.40 * max(0.0, 1.0 - position / 30.0)
    if word.isdigit():
        value += 0.54 * (1.0 - longer_growth)
        if re.fullmatch(r'\s*\d+', text.split('\n')[-1]):
            value -= 0.44
    elif word.isalpha():
        value += 0.013 * min(len(word), 10)
        if len(word) == 1:
            value -= 0.10 + 0.15 * longer_growth
        if word.isupper():
            value -= 0.18
            name = re.search(r'([^\W\d_]{2,})\s+$', before_word)
            if len(word) == 1 and name and name.group(1).istitle():
                value -= 0.34
        # Lowercase 'art' is usually the noun, not an article reference.
        if (word.lower() in ABBREVIATIONS and word != 'art'
                and not before_word[-1:].isdigit()):
            value -= 0.36 + 0.48 * longer_growth
        scripts = ' '.join(unicodedata.name(c, '') for c in word)
        if any(s in scripts for s in ('CYRILLIC', 'ARABIC', 'CJK', 'HIRAGANA')):
            value -= 0.32
    if re.search(r'\bet al$', text):
        value -= 0.43
    return float(value)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, '', 0)
    _, position, text, length = carry
    token = prefix.token_strings[-1]
    value = 0.0
    if token == '.':
        value = -0.06 if position == 0 else full_stop(text, length, position)
    elif token == '。':
        value = 0.13
    elif token.startswith(' '):
        if token.strip() == '.':
            value = 0.08
    elif not any(c.isalnum() for c in token):
        if '\n' in token and '.' in token:
            value = -0.02 if token.startswith('.\n') else -0.15
        elif token.endswith('.'):
            if '%' in token:
                value = 1.10
            elif '$' in token:
                value = 1.00
            elif '()' in token or "')" in token or '")' in token:
                value = 0.13
            elif any(c in token for c in ')]}'):
                value = 0.72
            else:
                value = 0.75
        elif token.startswith('.') and any(c in token for c in '\"“”‘’'):
            value = 0.47
        elif token in ('.,', '.;', '.-'):
            value = -0.20
    pieces = re.split(r'[.!?\n]', token)
    length = min(200, len(pieces[-1]) if len(pieces) > 1 else length + len(token))
    return (doc, position + 1, (text + token)[-200:], length), float(value)

