import re

READS = ()
RESULT = set('therefore thus hence consequently accordingly so'.split())
CONTRAST = set(
    'however nevertheless nonetheless alternatively instead otherwise conversely'.split()
)
THOUGHT = set('wait hmm well okay ok yes no indeed actually alright'.split())
SEQUENCE = set(
    'first second third finally lastly next furthermore moreover additionally'.split()
)
SUBORDINATORS = set(
    'when while if unless although though since because after before once until '
    'whenever wherever whereas as'.split()
)
RESPONSES = set('oh ah yeah sure certainly absolutely hello hey wow oops'.split())
