def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        n, text = 0, ''
    else:
        _, n, text = carry
    token = prefix.token_strings[-1]
    stripped = token.strip()
    new_carry = (doc, n + 1, (text + token)[-400:])
    early = 1.0 / (1.0 + n / 4.0)

    if stripped == '<|endoftext|>':
        return new_carry, 1.68
    if not any(ch in token for ch in ',，、،'):
        return new_carry, 0.0

    before = text.rstrip()
    match = re.search(r'([^\W\d_]+|\d+)$', before)
    word = match.group(0) if match else ''
    lower = word.lower()
