"""layers.0.mlp.down_proj:3685 -- a "comma" neuron (negative on commas).

What it does: it writes a strong negative value at most commas and a positive value at
end-of-text. Its size depends on the short phrase in front of the comma:

  * a comma right after a one-word opener ("However,", "Today,", "Yes,") is the most
    negative (about -1.4); a comma after a number ("1,000", "2,") is about -1.2;
    after an adverb such as "Therefore," or "Thus," about -1.6;
  * a comma that closes an introductory "When/If/After/As/..." clause is only mildly
    negative (about -0.55), because the clause is still open;
  * any other comma is about -0.9;
  * the ideographic comma 、 is -1.2, the fullwidth comma ， is -0.6, and other tokens that
    end in a comma, such as `",` `.,` or `),`, about -0.5;
  * the end-of-document token <|endoftext|> is +1.7;
  * every other token predicts 0.

The sentence start is tracked in `carry`: a sentence starts after a newline, a period,
a question or exclamation mark, or a document boundary.
"""

READS = ()

# Words that open a subordinate or introductory clause ("When the rain stopped, ...").
OPENERS = {
    "When", "If", "After", "As", "Since", "While", "Once", "Although", "Because", "Before",
    "Until", "Unless", "Whenever", "Having", "Given", "During", "Upon", "Though", "Whether",
    "In", "For", "At", "On", "By", "With",
}
# Short discourse words that often stand alone before a comma ("However, ...").
ADVERBS = {"However", "Therefore", "Thus", "So", "Yes", "Alternatively", "Wait", "Today", "Then"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[2] != doc:  # a new row or document starts a new sentence
        carry = ("", "", doc, 0)
    first, prev, _, n = carry  # first word of this sentence, previous token, doc, tokens so far

    value = 0.0
    if tok == ",":
        value = -0.9
        if first in OPENERS:
            value = -0.55
        if n == 1 and first not in OPENERS:  # comma after a one-word phrase
            value = -1.4
        if prev.isdigit():
            value = -1.2
        elif prev.strip() in ADVERBS:
            value = -1.6
    elif tok == "，":
        value = -0.6
    elif tok == "、":
        value = -1.2
    elif tok.endswith(","):
        value = -0.5
    elif tok == "<|endoftext|>":
        value = 1.7

    # Update the sentence state for the next position.
    if tok == "<|endoftext|>" or "\n" in tok or tok.strip() in (".", "!", "?"):
        first, n = "", 0
    else:
        if not first and tok.strip():
            first = tok.strip()
        n += 1
    return (first, tok, doc, n), value

