import re

READS = ()
GERMAN = set('der die das dem den des und ist sind nicht ein eine einen '
             'einer eines im zu mit auf für von sich auch als wird'.split())
CONSONANTS = set('bcdfghjklmnpqrstvwxzſ')
ENDINGS = set('ung ungen ern nen ren ten ien ier ierung gende genden '
              'lichkeit'.split())


def nasal_syllable(w):
    # Baseline, preceding-consonant bonus, German-context bonus.
    if re.fullmatch(r'en[e]*n?', w):
        return -0.078, 0.093, 0.335
    if w == 'end':
        return 0.202, 0.506, 0.335
    if w in {'ende', 'enden'}:
        return 0.315, 0.506, 0.335
    if re.fullmatch(r'ens(?:e|en)?', w):
        return -0.023, 0.506, 0.335
    if re.fullmatch(r'en(?:[gkvh][rl]?|t[hr])e?', w) or w == 'ensch':
        return 0.329, 0.506, 0.335
    if w == 'ent':
        return 0.080, 0.093, 0.335
    return (0.040, 0.0, 0.199) if len(w) <= 5 else (0.0, 0.0, 0.0)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    _, previous, stem, german = (doc, '', '', 0.0) if first else carry
    s = prefix.token_strings[-1]
    w = s.lower()
    previous_tail = re.search(r'[a-zſ]+$', previous.lower())
    tail = previous_tail[0] if previous_tail else ''
    c = float(bool(tail) and tail[-1] in CONSONANTS)
    vowel = float(bool(set(stem) & set('aeiouy')))
    g = min(8.0 * german, 1.0)
    value = 0.0003 - 0.0163 * first
    if s.isascii() and s.isalpha():
        letters = set(w)
        value += 0.0055 + 0.0095 * c
        e_only = w.startswith('e') and not letters & set('aiouy')
        if e_only and len(w) <= 4:
            value -= 0.031
            value += 0.1288 * g + 0.0483 * vowel
        if e_only and 2 <= len(w) <= 5:
            value += 0.1288 * g + 0.0483 * vowel
        if 2 <= len(w) <= 4:
            if not letters & set('aeiouy'):
                value += -0.0018 + 0.0427 * c + 0.1517 * g + 0.0483 * vowel
            elif 'y' in w and not letters & set('aeiou'):
                value += 0.0161 + 0.0242 * c
        if s == w and w.startswith('en'):
            base, consonant_bonus, german_bonus = nasal_syllable(w)
            value += base + consonant_bonus * c + german_bonus * g
            value += 0.1777 * vowel
            if len(previous) == 1 and previous.isupper():
                value -= 0.1376
            if tail.endswith('op') and re.fullmatch(r'en[st][a-z]{0,2}', w):
                value += 2.2019
            if tail.endswith('eig') and len(w) <= 5 and e_only:
                value += 1.2368
        if w in ENDINGS:
            value += -0.0219 + 0.1993 * g + 0.0483 * vowel
    if 'ー' in s and '\ufffd' in s:
        value += 0.3979
    if s == '<tool_response>':
        value -= 0.1879
    joined = stem + w if w and w[0].isalpha() else w
    word_tail = re.search(r'[a-zſ]+$', joined)
    stem = word_tail[0][-30:] if word_tail else ''
    german = 0.96 * german + 0.04 * (w.strip() in GERMAN)
    return (doc, s, stem, german), float(value)

