"""A spelling-boundary signal for t followed by i versus a.

Short i-like continuations after t are positive; a-like continuations are
negative. Fragment length and camel-case word breaks weaken the signal.
The common endings -ing/-ion weaken the i response, while -ation/-ative
and -able strengthen the negative a response. Otherwise, short ti fragments
inside one token also respond. State resets at each document boundary.
"""
import math
import unicodedata
from functools import lru_cache

READS = ()
# Group t letters and i/a-like continuations across several scripts.
_TRANSLATE = str.maketrans({
    'т': 't', 'τ': 't', 'ت': 't', 'ต': 't',
    'и': 'i', 'і': 'i', 'ι': 'i', 'ي': 'i', 'ی': 'i', 'ิ': 'i',
    'а': 'a', 'α': 'a', 'я': 'y', 'ь': 'y',
    'е': 'e', 'у': 'u', 'о': 'o', 'ё': 'y', 'ю': 'y',
})

@lru_cache(maxsize=8192)
def letters(raw):
    text = raw.lower().translate(_TRANSLATE)
    result = ''
    for c in text:
        base = unicodedata.normalize('NFD', c)[0]
        # Fold accented vowels, not consonants such as Romanian ț (= ts).
        result += base if base in 'aeiouyαιουηε' else c
    return result.translate(_TRANSLATE)

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    raw = prefix.token_strings[-1]
    text = letters(raw)
    previous, upper = carry[1:] if carry and carry[0] == doc else ('', False)
    value = 0.0
    boundary = previous.endswith(('t', 'th')) and not text[:1].isspace()
    if boundary and text:
        c = text[0]
        decay = 0.08 if c == 'a' else 0.23
        strength = math.exp(-decay * max(0, len(previous.strip()) - 3))
        if previous.endswith('th'):
            strength *= 0.55
        if raw[:1].isupper() and not raw.isupper() and not upper:
            strength *= 0.35
        n = len(text.strip())
        if c == 'i':
            value = 2.0 + (0.17 if n == 1 else 0.0)
            if text.startswith('ing'):
                value -= 1.5
            if text.startswith('ion'):
                value -= 0.55
            value *= math.exp(-0.25 * max(0, n - 2))
        elif c == 'a':
            value = -0.65
            if text.startswith(('ation', 'ativ')):
                value -= 0.75
            if text.startswith('ab'):
                value -= 0.57
            if n > 1 and text[1] in 'eiou':
                value += 0.6
            value *= math.exp(-0.4 * max(0, n - 6))
        elif c in 'yjě':
            value = 1.0
        elif c in 'uыı':
            value = 0.4
        value *= strength
    elif not boundary:
        fragment = text.strip()
        n = len(fragment)
        index = fragment.rfind('ti')
        if index >= 0 and n - index <= 3 and n <= 4:
            value = 0.92 if n == 2 else 0.46
            if n - index == 3 and fragment[-1] in 'aeiou':
                value *= 0.35
    return (doc, text, raw.strip().isupper()), value

