FILE_EXTENSIONS = {"py", "js", "ts", "tsx", "jsx", "html", "json", "yml", "yaml", "log",
                   "txt", "css", "xml", "php", "sh"}
CODE_MEMBERS = {"append", "push", "println", "printf", "get", "set", "add", "join", "find",
                "includes", "create", "replace", "parse", "run", "length", "count", "value",
                "type", "getItem", "setItem"}
CODE_WORDS = ("self", "this", "console", "function", "const ", "def ")
URL_OR_PACKAGE = ("://", "www", "import ", "package ")


def _recent_text(prefix, n=30):
    """The last n tokens of the same document, joined as text."""
    k = len(prefix.token_strings)
    start = max(0, k - n)
    doc = prefix.document_ids[-1]
    while start < k - 1 and prefix.document_ids[start] != doc:
        start += 1
    return "".join(prefix.token_strings[start:])


def step(carry, prefix, upstream):
    """Activation at the newest token: its strength as a dotted-name segment, else 0."""
    tok = prefix.token_strings[-1]
    if len(tok) < 2 or tok[0] != "." or not tok[1].isalpha():
        return carry, 0.0
    word = tok[1:]
    text = _recent_text(prefix)
    value = 0.7
    if len(word) == 1:
        value += 0.4
    if any(w in text for w in URL_OR_PACKAGE):
        value += 0.4
    if word in FILE_EXTENSIONS:
        value -= 0.5
    elif word in CODE_MEMBERS:
        value -= 0.25
    if word[0].isupper():
        value -= 0.4
    if any(w in text for w in CODE_WORDS):
        value -= 0.2
    return carry, max(value, 0.0)

