RELATED_SEPARATORS = {
    '‐': -0.75,
    '‑': -0.75,
    ' −': 0.05,
    '··': -0.24,
}
DASH_STYLES = {
    '-', ' -',
    '–', ' –',
    '--', ' --',
    '—', ' —',
}


