    "likely", "certainly", "definitely", "actually", "obviously",
}
ASPECT = {"still", "also", "only", "just", "already", "then", "otherwise"}
THOUGHT = {"think", "say", "know", "assume", "imagine"}
PREFERENCE = {"like", "want", "need", "prefer"}
