from functools import lru_cache

READS = ()
# Masculine/feminine and singular/plural agreement endings.
E_ENDINGS = {'é': 3.7, 'és': 1.94, 'ée': .97, 'ées': .78}


@lru_cache(maxsize=8192)
def response(token):
    letters = ''.join(c for c in token if c.isalpha())
    word = letters.lower()
    if 'é' in word:
        if word in E_ENDINGS:
            size = E_ENDINGS[word]
        else:
            i = word.rfind('é')
            size = 3.7 * (1, 1, .55, .42, .24, .14)[min(i, 5)]
            size *= (1, .46, .22, .16, .10)[min(len(word) - i - 1, 4)]
        if token.startswith(' '):
            size *= .73
        if token.startswith(("'", '’')):
            size *= .75
        if letters[0].isupper():
            size *= 1.18
        if 'É' in letters:
            size *= 1.18
        return -size, token.startswith('é')
    strength = 0.0
    for vowel, size in [('á', .7), ('ó', .28), ('ú', .45), ('ý', .23),
                        ('à', .35), ('è', .6), ('ù', .5), ('έ', .69)]:
        if vowel in word:
            strength = max(strength, size)
    if 'í' in word:
        strength = max(strength, .1 if word.startswith('í') else .4)
    if token.startswith(' ') and ('á' in word or 'è' in word):
        strength *= .65
    return -strength / max(1.0, len(word) / 2), False


