    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value, suffix = response(token)
    if suffix and previous:
        stem = ''.join(c for c in previous if c.isalpha())
        size = 4.75 - .38 * min(len(stem), 6)
        size += .74 * any(c.isupper() for c in stem)
        size -= .5 * bool(stem and stem[-1].lower() in 'aeiou')
        size += .4 * any(ord(c) > 127 for c in stem)
        value *= max(.4, min(1.6, size / 3.7))
    if token.strip() == '©':
        damaged = any(c in previous for c in 'ÃГ�')
        value = (-2.7 if token.startswith(' ') else -4.5) if damaged else -1.35
    elif token == "\\'":
        value = -.52
    elif token == '\\xa':
        value = -.08 if previous == '0' else -.65
    elif token == '\\xc':
        value = -.34
    elif token == '9' and previous.endswith('\\x'):
        value = -1.0
    elif token == 'e':
        value = -.14
    elif token == 's':
        value = -.04
    return (doc, token), float(value)

