    ('such', 0.14),
    ('well known defined far soon', -0.01),
    ('described seen calculated identified represented', -0.25),
    ('used worked working', -1.95),
    ('use using work serve served serves serving act acted acts acting '
     'employ employed hired function functioning behave behaves', -1.55),
    ('it them me him her us you themselves myself itself', -1.10),
    ('be was were', -1.20),
    ('been being is are not', -0.87),
    ('and but or so same long much exception error', -0.30),
    ('to of', -0.50),
)
AS_AFTER = [(set(words.split()), value) for words, value in AS_AFTER]
