    for words, value in AS_AFTER:
        if p in words:
            return value
    if p.isdigit():
        return -0.55
    return -0.30 if p.endswith((')', ']', ';')) else -0.73


def punctuation(text):
    s = text.strip()
    if not 2 <= len(s) <= 24 or any(c.isalnum() or c == '\ufffd' for c in s):
        return 0.0
    first, last = s[0], s[-1]
    if all(c in '。，、' for c in s):
        return 4.0
