        if first in '\'"`”’»':
            value = 0.15 + 0.55 * text.startswith(' ')
            return value + 1.5 * (s.count(',') > 1)
        if ':' in s:
            value = 2.5 if first in '([' else 1.4
        elif first in '?!;':
