        if len(s) == 2 and last in ';:!?':
            return 1.4
        return 0.8 if last in ')-*+/' else 0.15
    if first == '?':
        if last in '.:':
            return 2.5 if last == '.' else 1.5
        return 0.8 if last in '?);-' else 0.0
    if first == ':':
        if last == '.':
            return 2.5
        if ':' in s[1:]:
