READS = ()

# Typical activation on each word, in the component's units (negative = component active).
STRONG = {"inside": -7.5, "outside": -7.5}
MEDIUM = {"within": -1.5, "underneath": -2.0, "outdoor": -1.1, "outdoors": -1.3}
WEAK = {
    "before": -0.8, "beside": -0.8, "beneath": -0.7, "exterior": -0.75, "enclosed": -0.7,
    "indoor": -0.7, "nearby": -0.75, "under": -0.45, "opposite": -0.4, "interior": -0.3,
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    same_doc = len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2].strip().lower() if same_doc else ""
    for table in (STRONG, MEDIUM, WEAK):
        if word in table:
            return None, table[word]
    # The word right after "outside" / "inside" (as in "outside of", "inside the").
    if prev in ("outside", "inside"):
        if word == "of":
            return None, -3.0
        if word == "the":
            return None, -1.6
    if prev == "within" and word == "the":
        return None, -0.6
    return None, 0.0

programs.sol:
"""A spelling-based bottom/base signal, with weaker spatial and thoroughness cues.

Bottom dominates, followed by top, middle and ground. Includes Chinese
bottom/top/foundation spellings. 'The' strengthens selected nouns; otherwise a recent
top weakens bottom. The signal echoes on a following 'of' and on
'ed' completing bottomed. Everything resets at document boundaries.
CSS margin/padding-bottom is weaker. Other tokens get a near-zero baseline.
Small, unrelated lexical and broken-byte responses are left unmodeled.
"""

READS = ()

SPATIAL = {'middle': -1.08, 'ground': -0.97, 'back': -0.8, 'base': -0.8}
LOW_AND_FOUNDATION = set('''low foot floor bases backing grounded basal
basement foundation fundamental underneath thorough'''.split())
COMPLETENESS = {'comprehensive': -0.88, 'prehensive': -1.23,
                'exhaust': -0.75, 'thoroughly': -0.44}
CHINESE = {
    '底': -6.5, '底部': -5.1,  # bottom
    '底层': -2.4, '底下': -2.4, '底线': -2.4,
    '到底': -1.9, '心底': -1.9,
    '年底': -3.3, '月底': -1.5,  # year/month end
    '顶': -2.0, '頂': -1.36, '顶部': -2.0,  # top
    '低': -1.13, '最低': -1.87,  # low/lowest
    '基础': -0.65, '基礎': -0.38, '根本': -1.33,  # foundations
}
ARTICLE_GAIN = {'base': -0.17, 'ground': -0.15, 'back': -0.23,
                'middle': -0.13, 'low': -0.17}
EDGES = ' \t\r\n._-/\\()[]\'"'


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, last, recent = '', 0.0, ()
    else:
        _, previous, last, recent = carry
    token = prefix.token_strings[-1]
    word = token.strip(EDGES).lower()
    definite = previous.lower() == 'the'
    if word == 'bottom':
        signal = -7.35 if token.startswith(' ') else -6.8
        if definite:
            signal = -8.03
        elif 'top' in recent:
            signal = -6.7
        if token == '-bottom' and previous in {'margin', 'padding'}:
            signal = -5.85
    elif word == 'bottoms':
        signal = -6.2
    elif word == 'top':
        signal = -2.0 if definite else -1.6
    elif token.strip() in CHINESE:
        signal = CHINESE[token.strip()]
        if word == '底' and previous == '徹':
            signal = -1.5  # 徹底: thoroughly, not literal bottom.
    else:
        signal = SPATIAL.get(word, COMPLETENESS.get(word, 0.0))
        if word in LOW_AND_FOUNDATION:
            signal = -0.65
        if definite:
            signal += ARTICLE_GAIN.get(word, 0.0)
    value = signal if signal else -0.003
    if token in {' of', ' Of'} and last:
        value = 0.65 * last
    elif token == 'ed' and previous.strip(EDGES).lower() == 'bottom':
        value = 0.55 * last
    recent = (recent + (word,))[-4:]
    return (doc, token.strip(), signal, recent), float(value)

programs.haiku:
"""Layer-0 MLP down-projection component 3709: a "position within something" noun detector.

What it does: it writes a negative value into the residual stream on nouns that name a
position inside or under an object or place, most strongly "bottom" (and "底", the Chinese
word for bottom/base):
  - bottom, 底                       about -7.5   ("the bottom", "bottom line")
  - top, 顶                          about -1.5   ("the top", "top of")
  - middle, ground, base, back, low  about -0.7 to -1.1
    (also the weaker floor, foot, foundation, fundamental: about -0.6)
  - the word "of" right after "bottom" (about -5), or after "top" (about -1)
Every other token gets 0. The value depends only on the current token and the one before
it, with no carry between positions. Words such as "mid", "peak", "summit" are near 0 and
are left out.

Why: the activation is almost a pure function of the current token's identity (an oracle
per-token table explains ~83% of its variance). The table below is the concept; the
numbers are rounded per-group means measured on training text.
"""

READS: tuple[str, ...] = ()

BOTTOM = {"bottom", "bottoms", "-bottom", "底"}
BOTTOM_VALUE = -7.5

TOP = {"top", "tops", "顶", "頂"}
TOP_VALUE = -1.5

MIDDLE = {"middle"}
MIDDLE_VALUE = -1.1

GROUND_BASE = {"ground", "grounds", "base", "bases", "_base", "基地", "基础"}
GROUND_BASE_VALUE = -0.9

BACK_LOW = {"back", "backs", "-back", "low", "lowest", "低", "最低"}
BACK_LOW_VALUE = -0.8

FLOOR_FOOT = {"floor", "floors", "foot", "footing", "foundation", "fundamental"}
FLOOR_FOOT_VALUE = -0.6

OF_AFTER_BOTTOM = -5.5
OF_AFTER_TOP = -1.0


def word_value(word):
    if word in BOTTOM:
        return BOTTOM_VALUE
    if word in TOP:
        return TOP_VALUE
    if word in MIDDLE:
        return MIDDLE_VALUE
    if word in GROUND_BASE:
        return GROUND_BASE_VALUE
    if word in BACK_LOW:
        return BACK_LOW_VALUE
    if word in FLOOR_FOOT:
        return FLOOR_FOOT_VALUE
    return 0.0


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word == "of" and len(prefix.token_strings) > 1:
        before = prefix.token_strings[-2].strip().lower()
        if before in BOTTOM:
            return None, float(OF_AFTER_BOTTOM)
        if before in TOP:
            return None, float(OF_AFTER_TOP)
    return None, float(word_value(word))

programs.sol:
"""Partial approximation of mixed typography and local-grammar biases.

Closing tool-response tags, embedded line breaks and short tab-plus-space
forms get negative offsets. Capitals, numeric symbols, plural demonstratives
and some separators get positive offsets. Short English constructions add
signed corrections. Most token-specific variation remains unmodeled.
Only the previous token is retained, reset at document boundaries.
"""
import unicodedata

READS = ()
INFINITIVE_CUES = {
    'going', 'trying', 'try', 'able', 'willing', 'supposed', 'order', 'how'
}
CAUSAL_LEAD = {'lead', 'leads', 'led', 'leading'}
COMPARATIVES = {'more', 'less', 'greater', 'higher', 'lower', 'better', 'rather'}
# Articles, subject pronouns, and the conjunction "and".
COMMA_FOLLOWERS = {
    'the', 'a', 'an', 'and', 'it', 'i', 'we', 'you', 'he', 'she', 'they'
}


def step(carry, prefix, upstream):
    doc, s = prefix.document_ids[-1], prefix.token_strings[-1]
    prev = carry[1] if carry is not None and carry[0] == doc else ''
    core = s.strip()
    w, p = core.lower(), prev.strip().lower()
    han = any('CJK' in unicodedata.name(c, '') for c in s)
    value = 0.00037

    # Current-token typography and familiar grammatical words.
    if s == '</tool_response>':
        value -= 0.13277
    if core.isupper() or core.istitle():
        value += 0.00337
    if len(core) == 1 and unicodedata.category(core) == 'No':
        value += 0.03576
    if w == 'how':
        value -= 0.04467
    if w in {'these', 'those'}:
        value += 0.021
    if core == "'" and not s.startswith(' ') and '\n' not in s:
        value -= 0.0252
    if '\n' in s and core:
        value -= 0.00827
    if s.isspace() and '\t' in s and '\n' not in s:
        spaces = s.count(' ')
        if 2 <= spaces <= 5:
            value -= 0.03104
        elif spaces >= 6:
            value += 0.02251

    # Immediate separator and grammatical context.
    if prev == '-':
        value += 0.02824 + (0.10093 if han else 0.0)
    if prev in {'·', '・'} and han:
        value += 0.09011
    if w == 'to' and p in INFINITIVE_CUES:
        value += 0.04514
    if w == 'to' and p in CAUSAL_LEAD:
        value -= 0.06615
    if w == 'than' and p in COMPARATIVES:
        value -= 0.04891
    if w == 'of' and p in {'number', 'numbers'}:
        value += 0.03957
    if w == 'the' and p == 'at':
        value += 0.03549
    if prev == ',' and w in COMMA_FOLLOWERS:
        value -= 0.01766
    if s == '<|im_end|>':
        if prev == '</tool_response>':
            value -= 0.05111
        elif prev in {'.', '?', '!'}:
            value += 0.043
    return (doc, s), float(value)

"""Approximate a multilingual lexical detector of generic references to people.

'People', 'person', and indefinite human pronouns give the strongest response.
The character 人 has the same role in Chinese and Japanese, with weaker
responses in compound words. Specific human nouns and related words are
weaker still. Capitalization and joined word pieces reduce some responses.
Locative words 'upon', 'unto', 'under', and lake words have negative
responses. Conversation delimiters get small format-dependent corrections.
Unlisted tokens return zero: smaller spelling-specific and contextual
responses are deliberately omitted. The program needs no history or state.
"""
READS = ()

ONE_PRONOUNS = {'someone', 'anyone'}
BODY_PRONOUNS = {'somebody', 'anybody', 'everybody'}
PERSON_PLURALS = {
    'persons', 'personas', 'personnes', 'persone', 'pessoas', 'personen',
}
FOREIGN_PERSON_WORDS = {
    'persona', 'menschen', 'mensch', 'leute',
    'люди', 'людей', 'человек', 'человека', 'человеку', 'kişi', 'gente',
}
FOREIGN_HUMAN_PRONOUNS = {
    'jemand', 'niemand', 'alguien', 'alguém', 'nadie', 'ktoś', 'никто',
}
HUMAN_RELATED = {
    'humans', 'humanity', 'mankind', 'individual', 'individuals',
    'personal', 'personnel', 'whoever', 'whomever',
}
CHINESE_GENERIC_PEOPLE = {
    '一个人', '一個人', '其他人', '所有人', '每个人',
    '每個人', '没有人', '沒有人', '很多人', '有些人', '被人', '让人', '讓人',
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    spelling = token.strip()
    word = spelling.lower()
    spaced = token[:1].isspace()
    capital = spelling[:1].isupper()
    if word == 'people':
        value = 0.77 if spaced or capital else 0.65
    elif word == 'person':
        if spaced:
            value = 0.65 if capital else 0.76
        else:
            value = 0.57 if capital else 0.47
    elif word in ONE_PRONOUNS:
        value = 0.74 if word == 'anyone' else 0.69
        if capital:
            value = 0.65
        if not spaced:
            value = 0.57
    elif word == 'everyone':
        value = 0.60 if spaced else 0.49
    elif word in BODY_PRONOUNS:
        value = 0.60 if word == 'anybody' else 0.47
        if capital:
            value = 0.35
    elif word == 'nobody':
        value = 0.35
    elif word in PERSON_PLURALS:
        value = 0.36
    elif word in {'personne', 'người', '사람'}:
        value = 0.51
    elif word == 'pessoa':
        value = 0.43
    elif word in FOREIGN_PERSON_WORDS:
        value = 0.28
    elif word in FOREIGN_HUMAN_PRONOUNS:
        value = 0.43
    elif word == 'man':
        value = (0.17 if capital else 0.27) if spaced else 0.06
    elif word in {'folks', 'peoples'}:
        value = 0.28
    elif word == 'human':
        value = 0.21
    elif word in {'something', 'everything', 'anything', 'nothing', 'others'}:
        value = 0.10
    elif word in HUMAN_RELATED:
        value = 0.17
    elif spelling == '-person':
        value = 0.45
    elif spelling in {'人', '的人', '有人', 'の人'}:
        if spelling == '人':
            value = 0.64
        elif spelling == 'の人':
            value = 0.62
        else:
            value = 0.79
    elif spelling in CHINESE_GENERIC_PEOPLE or spelling == '人的':
        value = 0.55
    elif spelling in {'给人', '給人', '令人', '人都', '人が'}:
        value = 0.37
    elif spelling in {'一人', '两个人', '兩個人', '多人', '用人'}:
        value = 0.38
    elif spelling in {'别人', '別人', '两人', '兩人', '三人', '众人'}:
        value = 0.30
    elif spelling.startswith('人') and len(spelling) <= 3:
        value = 0.25 if spelling != '人民币' else 0.0
    elif word == 'upon':
        value = -0.36 if spaced and not capital else -0.25
    elif word == 'unto' and spaced:
        value = -0.21
    elif word in {'under', 'underneath'}:
        value = -0.075
    elif word == 'lake':
        value = -0.28 if spaced else -0.15
    elif word == 'lakes':
        value = -0.17
    elif spelling == '湖':
        value = -0.51
    elif spelling in {'个人', '個人'}:
        value = 0.20
    elif spelling in {'<think>', '</think>'}:
        value = 0.13
    elif spelling == '<|im_start|>':
        value = 0.07
    elif spelling == '<|im_end|>':
        value = -0.05
    elif spelling in {
        '<tool_call>', '</tool_call>', '<tool_response>', '</tool_response>',
    }:
        value = -0.07
    else:
        value = 0.0
    return None, value

programs.haiku:
"""Layer-0 MLP down-projection component 3711: a "person word" detector.

The component reads the current token only. It responds when the token names a person or
people, and it predicts about 0 on almost every other token:

- strong (about 0.77): the nouns "person", "people", "persons" and their capitalised forms,
  and the Chinese 人 as a standalone word or in phrases such as 有人, 的人, 人们.
- strong (about 0.68): the indefinite pronouns for a person: someone, anyone, everyone,
  somebody, anybody, everybody, nobody.
- medium (about 0.27): "man".
- weak (about 0.2): other human-reference words (human, humans, individuals, folks,
  others) and person words in other languages (personas, personne, Menschen, человек,
  людей, osób, ...).
- faint (about 0.12): "personal", "personnel", "personality".
- other Chinese words containing 人 (for example 人口, 人生): about 0.25.

Everything else is 0. The program carries no state: each token's value depends only on
that token's own text, so it is the same wherever the token falls in a document.
"""

READS = ()

PERSON_NOUNS = {
    "person", "people", "persons", "peoples",
    "人", "有人", "的人", "人们", "人都", "人的", "让人", "有些人",
}
PERSON_PRONOUNS = {"someone", "anyone", "everyone", "somebody", "anybody", "everybody", "nobody"}
MAN = {"man"}
HUMAN_WORDS = {
    "human", "humans", "humanity", "mankind", "individuals", "individual", "folks", "others",
    "personas", "persona", "personne", "personnes", "persone", "menschen", "hombre", "gente",
    "человек", "человека", "людей", "люди", "ktoś", "osób",
}
PERSONAL = {"personal", "personnel", "personality"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in PERSON_NOUNS:
        value = 0.77
    elif word in PERSON_PRONOUNS:
        value = 0.68
    elif word in MAN:
        value = 0.27
    elif word in HUMAN_WORDS:
        value = 0.2
    elif word in PERSONAL:
        value = 0.12
    elif "人" in word:
        value = 0.25
    else:
        value = 0.0
    return carry, value
